import java.util.*;

class Solution {
  public int[] sortItems(int n, int m, int[] group, List<List<Integer>> beforeItems) {
    int groupCount = m;
    for (int i = 0; i < n; i++) if (group[i] == -1) group[i] = groupCount++;
    List<Integer>[] itemGraph = new List[n];
    List<Integer>[] groupGraph = new List[groupCount];
    for (int i = 0; i < n; i++) itemGraph[i] = new ArrayList<>();
    for (int i = 0; i < groupCount; i++) groupGraph[i] = new ArrayList<>();
    int[] itemIndegree = new int[n];
    int[] groupIndegree = new int[groupCount];
    for (int item = 0; item < n; item++) {
      for (int dependency : beforeItems.get(item)) {
        itemGraph[dependency].add(item);
        itemIndegree[item]++;
        if (group[dependency] != group[item]) {
          groupGraph[group[dependency]].add(group[item]);
          groupIndegree[group[item]]++;
        }
      }
    }
    List<Integer> groups = topologicalOrder(groupGraph, groupIndegree);
    if (groups.size() != groupCount) return new int[0];
    List<Integer> items = topologicalOrder(itemGraph, itemIndegree);
    if (items.size() != n) return new int[0];
    List<Integer>[] byGroup = new List[groupCount];
    for (int i = 0; i < groupCount; i++) byGroup[i] = new ArrayList<>();
    for (int item : items) byGroup[group[item]].add(item);
    int[] answer = new int[n];
    int index = 0;
    for (int currentGroup : groups) for (int item : byGroup[currentGroup]) answer[index++] = item;
    return answer;
  }

  private List<Integer> topologicalOrder(List<Integer>[] graph, int[] indegree) {
    Queue<Integer> queue = new ArrayDeque<>();
    for (int i = 0; i < indegree.length; i++) if (indegree[i] == 0) queue.offer(i);
    List<Integer> order = new ArrayList<>();
    while (!queue.isEmpty()) {
      int node = queue.poll();
      order.add(node);
      for (int next : graph[node]) if (--indegree[next] == 0) queue.offer(next);
    }
    return order;
  }
}
